import React from 'react';
import {
  Box,
  Typography,
  RadioGroup,
  FormControlLabel,
  Radio,
  Checkbox,
  FormGroup,
  TextField,
  FormControl,
  FormLabel,
  Chip,
  Grid,
} from '@mui/material';

// Fixed: Added safe array handling to prevent map errors on undefined arrays

const QuestionRenderer = ({ question, questionIndex, totalQuestions, currentAnswer, onAnswerChange }) => {
  console.log('QuestionRenderer received question:', question);
  console.log('Question type:', question?.type);
  console.log('Question properties:', Object.keys(question || {}));

  if (!question) {
    console.error('QuestionRenderer: question prop is null or undefined');
    return (
      <Box>
        <Typography variant="body1" color="error">
          Question data is not available.
        </Typography>
      </Box>
    );
  }

  if (!question.type) {
    console.error('QuestionRenderer: question.type is missing', question);
    return (
      <Box>
        <Typography variant="body1" color="error">
          Question type is not available.
        </Typography>
      </Box>
    );
  }

  const handleAnswerChange = (value) => {
    onAnswerChange(question._id, value);
  };

  const renderQuestionType = () => {
    console.log('renderQuestionType called for question type:', question.type);
    switch (question.type) {
      case 'multiple-choice':
        console.log('Multiple-choice question data:', {
          options: question.options,
          optionsType: typeof question.options,
          optionsIsArray: Array.isArray(question.options)
        });

        // Safe array access with defaults
        const options = Array.isArray(question.options) ? question.options : [];

        return (
          <FormControl component="fieldset">
            <FormLabel component="legend">{question.question}</FormLabel>
            <RadioGroup
              value={currentAnswer || ''}
              onChange={(e) => handleAnswerChange(e.target.value)}
            >
              {options.length > 0 ? (
                options.map((option, index) => (
                  <FormControlLabel
                    key={option._id || index}
                    value={option.text}
                    control={<Radio />}
                    label={option.text}
                  />
                ))
              ) : (
                <Typography variant="body2" color="error">
                  Options not available for this question.
                </Typography>
              )}
            </RadioGroup>
          </FormControl>
        );

      case 'short-answer':
        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {question.question}
            </Typography>
            <TextField
              fullWidth
              multiline
              rows={3}
              variant="outlined"
              value={currentAnswer || ''}
              onChange={(e) => handleAnswerChange(e.target.value)}
              placeholder="Enter your answer here..."
            />
          </Box>
        );

      case 'select-all':
        console.log('Select-all question data:', {
          options: question.options,
          optionsType: typeof question.options,
          optionsIsArray: Array.isArray(question.options),
          questionText: question.question
        });

        // Defensive check: ensure question.options exists and is an array
        if (!question.options || !Array.isArray(question.options)) {
          console.error('Select-all question: options is not an array or is undefined', question.options);
          return (
            <Typography variant="body2" color="error">
              Options not available for this select-all question.
            </Typography>
          );
        }

        // Safe array access with defaults
        const selectAllOptions = question.options;
        console.log('selectAllOptions array:', selectAllOptions);

        return (
          <FormControl component="fieldset">
            <FormLabel component="legend">{question.question}</FormLabel>
            <FormGroup>
              {selectAllOptions.length > 0 ? (
                selectAllOptions.map((option, index) => {
                  console.log('Mapping select-all option:', option, 'at index:', index);
                  return (
                    <FormControlLabel
                      key={option._id || index}
                      control={
                        <Checkbox
                          checked={currentAnswer?.includes(option.text) || false}
                          onChange={(e) => {
                            const newAnswer = e.target.checked
                              ? [...(currentAnswer || []), option.text]
                              : (currentAnswer || []).filter(item => item !== option.text);
                            handleAnswerChange(newAnswer);
                          }}
                        />
                      }
                      label={option.text}
                    />
                  );
                })
              ) : (
                <Typography variant="body2" color="error">
                  Options not available for this question.
                </Typography>
              )}
            </FormGroup>
          </FormControl>
        );

      case 'fill-in-the-blank':
        // Parse question text for [blank] placeholders
        const questionText = question.question || '';
        const blankRegex = /\[blank\]/g;
        const blanks = question.blanks || [];

        // Split question text by [blank] and create segments
        const segments = questionText.split(blankRegex);
        const blankCount = (questionText.match(blankRegex) || []).length;

        // Handle legacy format (single blank without [blank] placeholders)
        const hasLegacyFormat = !question.blanks && question.correctAnswer;
        const effectiveBlanks = hasLegacyFormat ? [{
          id: 'blank-1',
          correctAnswer: question.correctAnswer || '',
          alternativeAnswers: question.alternativeAnswers || [],
          keywordWeights: question.keywordWeights || {},
          gradingOptions: question.gradingOptions || {
            usePartialCredit: true,
            useSemanticSimilarity: true,
            useSynonyms: true,
            useStemming: true,
            useFuzzyMatching: true,
            fuzzyThreshold: 0.8,
            semanticWeight: 0.3,
            keywordWeight: 0.7,
            caseSensitive: false
          },
          size: 'medium',
          hint: '',
          points: 1
        }] : (blanks.length >= blankCount ? blanks : blanks.concat(
          Array(blankCount - blanks.length).fill().map((_, i) => ({
            id: `blank-${blanks.length + i + 1}`,
            correctAnswer: '',
            size: 'medium',
            hint: ''
          }))
        ));

        // For legacy format or if no [blank] placeholders found, add a single input at the end
        const finalSegments = blankCount === 0 && !hasLegacyFormat ? [questionText] :
                              blankCount === 0 && hasLegacyFormat ? [questionText, ''] : segments;
        const finalBlankCount = finalSegments.length - 1;

        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {finalSegments.map((segment, index) => (
                <React.Fragment key={index}>
                  {segment}
                  {index < finalSegments.length - 1 && (
                    <TextField
                      size={effectiveBlanks[index]?.size === 'small' ? 'small' : 'medium'}
                      label={effectiveBlanks[index]?.hint ? `Hint: ${effectiveBlanks[index].hint}` : `Blank ${index + 1}`}
                      value={(currentAnswer && currentAnswer[index]) || ''}
                      onChange={(e) => {
                        const currentAnswers = currentAnswer || [];
                        const newAnswers = [...currentAnswers];
                        newAnswers[index] = e.target.value;
                        handleAnswerChange(newAnswers);
                      }}
                      sx={{
                        mx: 1,
                        minWidth: effectiveBlanks[index]?.size === 'large' ? 200 :
                                 effectiveBlanks[index]?.size === 'small' ? 100 : 150,
                        verticalAlign: 'baseline'
                      }}
                      variant="outlined"
                      placeholder="Enter answer"
                    />
                  )}
                </React.Fragment>
              ))}
            </Typography>
          </Box>
        );

      case 'essay':
        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {question.question}
            </Typography>
            <TextField
              fullWidth
              multiline
              rows={6}
              variant="outlined"
              value={currentAnswer || ''}
              onChange={(e) => handleAnswerChange(e.target.value)}
              placeholder="Write your essay here..."
            />
          </Box>
        );

      case 'true-false':
        return (
          <FormControl component="fieldset">
            <FormLabel component="legend">{question.question}</FormLabel>
            <RadioGroup
              value={currentAnswer || ''}
              onChange={(e) => handleAnswerChange(e.target.value)}
            >
              <FormControlLabel value="true" control={<Radio />} label="True" />
              <FormControlLabel value="false" control={<Radio />} label="False" />
            </RadioGroup>
          </FormControl>
        );

      case 'matching':
        console.log('Matching question data:', {
          leftItems: question.leftItems,
          rightItems: question.rightItems,
          options: question.options,
          correctAnswer: question.correctAnswer,
          leftItemsType: typeof question.leftItems,
          rightItemsType: typeof question.rightItems,
          optionsType: typeof question.options,
          correctAnswerType: typeof question.correctAnswer
        });

        // Handle both new format (leftItems/rightItems) and old format (options/correctAnswer)
        let leftItems = [];
        let rightItems = [];

        // Safely extract arrays
        if (question.leftItems && Array.isArray(question.leftItems)) {
          leftItems = question.leftItems;
        }
        if (question.rightItems && Array.isArray(question.rightItems)) {
          rightItems = question.rightItems;
        }

        // If no leftItems from new format, try old format
        if (leftItems.length === 0 && question.options && Array.isArray(question.options)) {
          leftItems = question.options.map(opt => opt ? (opt.text || opt) : '');
          rightItems = Array.isArray(question.correctAnswer) ? question.correctAnswer : [];
        }

        // Ensure arrays are valid
        if (!Array.isArray(leftItems)) leftItems = [];
        if (!Array.isArray(rightItems)) rightItems = [];

        // If still no data, show error
        if (leftItems.length === 0 && rightItems.length === 0) {
          console.error('Matching question: No valid data format found', question);
          return (
            <Typography variant="body2" color="error">
              Matching question data is not available.
            </Typography>
          );
        }

        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {question.question}
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={6}>
                <Typography variant="subtitle1" gutterBottom>
                  Items to Match:
                </Typography>
                {leftItems.length > 0 ? (
                  leftItems.map((item, index) => (
                    <Box key={index} mb={1}>
                      <Chip label={item} />
                    </Box>
                  ))
                ) : (
                  <Typography variant="body2" color="error">
                    Left items not available.
                  </Typography>
                )}
              </Grid>
              <Grid item xs={6}>
                <Typography variant="subtitle1" gutterBottom>
                  Match with:
                </Typography>
                {rightItems.length > 0 ? (
                  rightItems.map((item, index) => (
                    <Box key={index} mb={1}>
                      <TextField
                        select
                        label={`Match ${item}`}
                        value={currentAnswer?.[item] || ''}
                        onChange={(e) => {
                          const newAnswer = { ...(currentAnswer || {}), [item]: e.target.value };
                          handleAnswerChange(newAnswer);
                        }}
                        SelectProps={{ native: true }}
                        fullWidth
                      >
                        <option value="">Select match</option>
                        {leftItems.length > 0 ? (
                          leftItems.map((leftItem, leftIndex) => (
                            <option key={leftIndex} value={leftItem}>
                              {leftItem}
                            </option>
                          ))
                        ) : (
                          <option disabled>No options available</option>
                        )}
                      </TextField>
                    </Box>
                  ))
                ) : (
                  <Typography variant="body2" color="error">
                    Right items not available.
                  </Typography>
                )}
              </Grid>
            </Grid>
          </Box>
        );

      case 'ordering':
        console.log('Ordering question data:', {
          items: question.items,
          itemsType: typeof question.items,
          itemsIsArray: Array.isArray(question.items),
          questionText: question.question
        });

        // Defensive check: ensure question.items exists and is an array
        if (!question.items || !Array.isArray(question.items)) {
          console.error('Ordering question: items is not an array or is undefined', question.items);
          return (
            <Typography variant="body2" color="error">
              Items not available for this ordering question.
            </Typography>
          );
        }

        // Safe array access with defaults
        const items = question.items;
        console.log('ordering items array:', items);

        return (
          <Box>
            <Typography variant="h6" gutterBottom>
              {question.question}
            </Typography>
            <Typography variant="body2" color="textSecondary" gutterBottom>
              Drag and drop to reorder the items correctly
            </Typography>
            {items.length > 0 ? (
              items.map((item, index) => {
                console.log('Mapping ordering item:', item, 'at index:', index);
                return (
                  <Box key={index} mb={1}>
                    <TextField
                      type="number"
                      label={`Position for: ${item}`}
                      value={currentAnswer?.[item] || ''}
                      onChange={(e) => {
                        const newAnswer = { ...(currentAnswer || {}), [item]: parseInt(e.target.value) };
                        handleAnswerChange(newAnswer);
                      }}
                      inputProps={{ min: 1, max: items.length }}
                      fullWidth
                    />
                  </Box>
                );
              })
            ) : (
              <Typography variant="body2" color="error">
                Items not available for ordering.
              </Typography>
            )}
          </Box>
        );

      default:
        return (
          <Typography variant="body1">
            Unknown question type: {question.type}
          </Typography>
        );
    }
  };

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        Question {questionIndex + 1} of {totalQuestions}
      </Typography>
      <Typography variant="body2" color="textSecondary" gutterBottom>
        Type: {question.type}
      </Typography>
      {question.points && (
        <Typography variant="body2" color="textSecondary" gutterBottom>
          Points: {question.points}
        </Typography>
      )}
      <Box mt={2}>
        {renderQuestionType()}
      </Box>
    </Box>
  );
};

export default QuestionRenderer;
